verifyCmd:
node <<'VERIFYJS'
const p = require('./parseRange.js');
const S = JSON.stringify;
const arr = (r) => (Array.isArray(r) ? r.map((x) => ({ start: x.start, end: x.end })) : r);
const eq = (got, want, m) => { if (S(arr(got)) !== S(want)) { console.error('FAIL', m, S(arr(got)), 'want', S(want)); process.exit(1); } };
eq(p(1000, 'bytes=0-499'), [{ start: 0, end: 499 }], 'simple');
eq(p(1000, 'bytes=500-'), [{ start: 500, end: 999 }], 'open end');
eq(p(1000, 'bytes=-500'), [{ start: 500, end: 999 }], 'suffix');
eq(p(1000, 'bytes=-2000'), [{ start: 0, end: 999 }], 'suffix larger than resource clamps');
eq(p(1000, 'bytes=0-2000'), [{ start: 0, end: 999 }], 'end clamps');
eq(p(1000, 'bytes=0-0'), [{ start: 0, end: 0 }], 'single byte');
eq(p(1000, 'bytes=0-99,200-299'), [{ start: 0, end: 99 }, { start: 200, end: 299 }], 'multiple in order');
eq(p(1000, 'bytes=200-299,0-99'), [{ start: 200, end: 299 }, { start: 0, end: 99 }], 'order preserved, not sorted');
eq(p(1000, 'bytes=0-99,5000-6000'), [{ start: 0, end: 99 }], 'unsatisfiable member dropped');
if (p(1000, 'bytes=-0') !== -1) { console.error('-0 must be unsatisfiable'); process.exit(1); }
if (p(1000, 'bytes=1000-') !== -1) { console.error('start at size is unsatisfiable'); process.exit(1); }
if (p(1000, 'bytes=2000-3000') !== -1) { console.error('wholly past end is unsatisfiable'); process.exit(1); }
for (const bad of ['bytes', 'bytes=', 'bytes=-', 'bytes=abc', 'bytes=100-50', '', null, undefined, '=0-9']) {
  if (p(1000, bad) !== -2) { console.error('must be malformed (-2):', S(bad), 'got', S(p(1000, bad))); process.exit(1); }
}
const typed = p(1000, 'items=0-9');
if (typed.type !== 'items') { console.error('unit not carried, got', typed.type); process.exit(1); }
console.log('ok');
VERIFYJS
